# Observed binary-outcome validation, explicit applicability and score boundaries.
.cr_validation_sample <- function(outcomes,predictions,weights,probability=FALSE) {
  y<-.cr_numeric(outcomes,'outcomes',vector_only=TRUE)
  p<-if(probability).cr_probability(predictions) else .cr_numeric(predictions,'scores',vector_only=TRUE)
  if(!is.null(dim(p))) .cr_error('INCOMPATIBLE_SHAPE','Validation requires one-dimensional observations')
  w<-if(is.null(weights))rep(1,length(y)) else .cr_numeric(weights,'weights',vector_only=TRUE)
  if(length(y)!=length(p)||length(y)!=length(w)) .cr_error('INCOMPATIBLE_SHAPE','Outcomes, predictions and weights need equal lengths')
  if(any(!(y %in% c(0,1)))) .cr_error('INVALID_OUTCOMES','Observed outcomes must be zero or one; missing outcomes are not zero')
  if(any(w<0)||!any(w>0)) .cr_error('INVALID_WEIGHTS','Nonnegative weights with positive total required')
  total<-sum(w);if(!is.finite(total)) .cr_error('NUMERICAL_RANGE','Weight sum exceeds finite range')
  list(y=y,p=p,w=w,total=total)
}
.cr_validation_groups <- function(y,score,w,direction) {
  if(!is.character(direction)||length(direction)!=1L||is.na(direction)||!(direction %in% c('higher_is_risk','lower_is_risk'))) .cr_error('INVALID_DIRECTION','Declare higher_is_risk or lower_is_risk')
  oriented<-if(direction=='higher_is_risk')score else -score
  active<-w>0;values<-sort(unique(oriented[active]));indices<-match(oriented[active],values)
  group_sum<-function(x) {result<-numeric(length(values));s<-rowsum(x,indices,reorder=FALSE);result[as.integer(rownames(s))]<-s[,1];result}
  list(values=values,positive=group_sum(w[active]*y[active]),negative=group_sum(w[active]*(1-y[active])),positive_count=group_sum(y[active]),negative_count=group_sum(1-y[active]))
}
auc_gini <- function(outcomes,scores,weights=NULL,score_direction,context=NULL) {
  s<-.cr_validation_sample(outcomes,scores,weights);g<-.cr_validation_groups(s$y,s$p,s$w,score_direction)
  ptotal<-sum(g$positive);ntotal<-sum(g$negative);pair_count<-sum(g$positive_count)*sum(g$negative_count);tie_count<-sum(g$positive_count*g$negative_count)
  if(ptotal==0||ntotal==0) value<-list(auc=NULL,gini=NULL,applicability='NOT_APPLICABLE',reason='ONE_CLASS',pair_count=pair_count,tied_pair_count=tie_count,concordant_pair_mass=NULL,tied_pair_mass=NULL) else {
    p<-g$positive/ptotal;n<-g$negative/ntotal;lower_negative<-c(0,head(cumsum(n),-1));concordance<-sum(p*lower_negative);ties<-sum(p*n);auc<-concordance+0.5*ties
    value<-list(auc=auc,gini=2*auc-1,applicability='APPLICABLE',reason=NULL,pair_count=pair_count,tied_pair_count=tie_count,concordant_pair_mass=concordance,tied_pair_mass=ties)
  }
  .cr_result(value,'validation.auc_gini','discrimination',context,diagnostics=list(score_direction=score_direction,event_weight=ptotal,nonevent_weight=ntotal,total_weight=s$total,excluded_zero_weight=sum(s$w==0),pair_mass_normalization='within_each_class'),limitations='Descriptive paired concordance; repeated entities and sample selection affect inferential interpretation. No confidence interval is implied.')
}
ks_discrimination <- function(outcomes,scores,weights=NULL,score_direction,context=NULL) {
  s<-.cr_validation_sample(outcomes,scores,weights);g<-.cr_validation_groups(s$y,s$p,s$w,score_direction);ptotal<-sum(g$positive);ntotal<-sum(g$negative)
  if(ptotal==0||ntotal==0) value<-list(ks=NULL,threshold=NULL,signed_difference=NULL,cdf=list(),applicability='NOT_APPLICABLE',reason='ONE_CLASS') else {
    pcdf<-cumsum(g$positive/ptotal);ncdf<-cumsum(g$negative/ntotal);difference<-ncdf-pcdf;index<-which.max(abs(difference));thresholds<-if(score_direction=='higher_is_risk')g$values else -g$values
    rows<-lapply(seq_along(thresholds),function(i)list(threshold=thresholds[i],event_cdf=pcdf[i],nonevent_cdf=ncdf[i]))
    value<-list(ks=abs(difference[index]),threshold=thresholds[index],signed_difference=difference[index],cdf=rows,applicability='APPLICABLE',reason=NULL)
  }
  .cr_result(value,'validation.ks_discrimination','discrimination',context,diagnostics=list(score_direction=score_direction,cdf_order='ascending_oriented_risk_score',total_weight=s$total,threshold_tie_break='first_in_ascending_oriented_score'),limitations='Descriptive KS distance only; weighted, tied or dependent data do not justify a classical continuous IID KS p-value.')
}
brier_score <- function(outcomes,predicted_pd,weights=NULL,context=NULL) {
  s<-.cr_validation_sample(outcomes,predicted_pd,weights,TRUE);loss<-(s$y-s$p)^2;contributions<-(s$w/s$total)*loss;rate<-sum((s$w/s$total)*s$y)
  .cr_result(list(brier=sum(contributions),contributions=as.list(contributions),squared_errors=as.list(loss),observed_rate=rate,outcome_variance_baseline=rate*(1-rate)),'validation.brier_score','mean_squared_probability_error',context,diagnostics=list(total_weight=s$total,excluded_zero_weight=sum(s$w==0)),limitations='Outcomes must be observed on the same target and horizon as predictions; this metric does not repair selection or censoring.')
}
log_loss <- function(outcomes,predicted_pd,weights=NULL,boundary_policy='exact',epsilon=NULL,context=NULL) {
  s<-.cr_validation_sample(outcomes,predicted_pd,weights,TRUE)
  if(!is.character(boundary_policy)||length(boundary_policy)!=1L||is.na(boundary_policy)||!(boundary_policy %in% c('exact','clip'))) .cr_error('INVALID_BOUNDARY_POLICY','Use exact or clip')
  if(boundary_policy=='exact'&&!is.null(epsilon)) .cr_error('INVALID_BOUNDARY_POLICY','Exact policy does not take epsilon')
  if(boundary_policy=='clip') {e<-.cr_numeric(epsilon,'epsilon');if(length(e)!=1L||!is.null(dim(e))||e<=0||e>=0.5) .cr_error('INVALID_BOUNDARY_POLICY','Explicit epsilon must lie in (0,.5)');used<-pmin(pmax(s$p,e),1-e);if(any(used<=0|used>=1)) .cr_error('INVALID_BOUNDARY_POLICY','Epsilon must produce representable interior bounds')} else used<-s$p
  losses<-numeric(length(s$y));losses[s$y==1]<- -log(used[s$y==1]);losses[s$y==0]<- -log1p(-used[s$y==0]);impossible<-is.infinite(losses)&s$w>0
  contributions<-lapply(seq_along(losses),function(i)if(s$w[i]==0)0 else if(is.infinite(losses[i]))NULL else s$w[i]/s$total*losses[i]);infinite<-any(impossible)
  .cr_result(list(log_loss=if(infinite)NULL else sum(unlist(contributions)),loss_status=if(infinite)'INFINITE' else 'FINITE',contributions=contributions,infinite_loss_flags=as.list(impossible)),'validation.log_loss','nats',context,diagnostics=list(total_weight=s$total,boundary_policy=boundary_policy,epsilon=epsilon,clipped_count=sum(used!=s$p),positive_infinity_representation='null plus INFINITE'),limitations='Predictions fixed before observing outcomes are required for an honest validation interpretation. Any clipping changes the scoring rule at the selected boundaries.')
}
binomial_pd_test <- function(n,observed_defaults,common_pd,alternative,independence_assumption,confidence_level=0.95,context=NULL) {
  count<-.cr_numeric(n,'n');k<-.cr_numeric(observed_defaults,'observed_defaults');p<-.cr_numeric(common_pd,'common_pd');confidence<-.cr_numeric(confidence_level,'confidence_level')
  if(any(vapply(list(count,k,p,confidence),function(x)length(x)!=1L||!is.null(dim(x)),logical(1)))||count<0||k<0||k>count||count!=floor(count)||k!=floor(k)||count>9007199254740991) .cr_error('INVALID_COUNTS','Require exact integer counts 0 <= defaults <= n')
  if(p<0||p>1||confidence<=0||confidence>=1) .cr_error('INVALID_PROBABILITY','PD in [0,1] and confidence in (0,1) required')
  if(!is.character(alternative)||length(alternative)!=1L||is.na(alternative)||!(alternative %in% c('two-sided','less','greater'))) .cr_error('INVALID_ALTERNATIVE','Declare two-sided, less or greater')
  if(!identical(independence_assumption,'independent_common_probability')) .cr_error('INCOMPATIBLE_ASSUMPTIONS','Binomial test requires declared independent common-probability trials')
  if(count==0) value<-list(p_value=NULL,lower=NULL,upper=NULL,observed_rate=NULL,applicability='NOT_APPLICABLE',reason='EMPTY_COHORT') else {
    test<-stats::binom.test(k,count,p,alternative=if(alternative=='two-sided')'two.sided' else alternative,conf.level=confidence)
    value<-list(p_value=as.numeric(test$p.value),lower=as.numeric(test$conf.int[1]),upper=as.numeric(test$conf.int[2]),observed_rate=k/count,applicability='APPLICABLE',reason=NULL)
  }
  .cr_result(value,'validation.binomial_pd_test','test',context,diagnostics=list(n=count,observed_defaults=k,common_pd=p,alternative=alternative,confidence_level=confidence,independence_assumption=independence_assumption,two_sided_ordering='probability_mass',interval_method='Clopper-Pearson'),limitations='Independent equal-probability trials are an explicit assumption; correlated obligors or heterogeneous PDs require a different null model.')
}

.cr_validation_design <- function(design,pd,allow_fitted=FALSE) {
 if(!.cr_object(design)) .cr_error('INVALID_VALIDATION_DESIGN','Explicit frozen-forecast design required')
 .cr_canonical(design);d<-design;.cr_data_required(d,c('prediction_origin','forecast_known_at','evaluation_at','split_id','target'))
 if(!is.character(d$split_id)||length(d$split_id)!=1L||!nzchar(d$split_id)) .cr_error('INVALID_VALIDATION_DESIGN','Nonempty split_id required')
 allowed<-if(allow_fitted)c('HOLDOUT','EXTERNAL','FITTED_SAMPLE') else c('HOLDOUT','EXTERNAL')
 if(!(d$prediction_origin %in% allowed)) .cr_error('INVALID_VALIDATION_DESIGN','Prediction origin incompatible with diagnostic')
 if(.cr_data_date(d$forecast_known_at,'forecast_known_at')>.cr_data_date(d$evaluation_at,'evaluation_at')) .cr_error('INVALID_VALIDATION_DESIGN','Forecast knowledge follows evaluation')
 if(!is.null(d$forecast_fingerprint)&&!identical(d$forecast_fingerprint,.cr_hash(as.list(as.numeric(pd))))) .cr_error('FORECAST_INTEGRITY','Frozen forecast fingerprint differs')
 d$forecast_fingerprint<-.cr_hash(as.list(as.numeric(pd)));d$target<-.cr_cal_target(d$target);if(d$target$probability_measure!='PHYSICAL') .cr_error('INCOMPATIBLE_TARGET','Observed default validation requires physical PD');d
}
.cr_validation_alternative<-function(alternative) {if(!is.character(alternative)||length(alternative)!=1L||is.na(alternative)||!(alternative %in% c('two-sided','less','greater'))) .cr_error('INVALID_ALTERNATIVE','Declare two-sided, less or greater')}
.cr_validation_confidence<-function(confidence_level) {value<-.cr_numeric(confidence_level,'confidence_level');if(length(value)!=1L||!is.null(dim(value))||value<=0||value>=1) .cr_error('INVALID_PROBABILITY','Confidence must lie in (0,1)');as.numeric(value)}
.cr_validation_bins<-function(pd,bin_edges) {edges<-.cr_probability(bin_edges,vector_only=TRUE);if(length(edges)<2L||edges[1]!=0||tail(edges,1)!=1||any(diff(edges)<=0)) .cr_error('INVALID_BINS','Prespecified increasing edges must cover [0,1]');list(edges=edges,assignment=pmin(findInterval(pd,edges),length(edges)-1L))}
calibration_intercept_slope<-function(predicted_pd,outcomes,design,covariance_policy,cluster_ids=NULL,confidence_level=.95,boundary_policy='reject',epsilon=NULL,max_iter=100,tolerance=1e-10,context=NULL) {
 s<-.cr_validation_sample(outcomes,predicted_pd,NULL,TRUE);y<-s$y;p<-s$p;d<-.cr_validation_design(design,p);confidence<-.cr_validation_confidence(confidence_level)
 if(!(covariance_policy %in% c('iid','cluster_cr1','none'))) .cr_error('INVALID_COVARIANCE_POLICY','Use iid, cluster_cr1 or none');groups<-NULL
 if(covariance_policy=='cluster_cr1') {if(is.list(cluster_ids))cluster_ids<-unlist(cluster_ids);if(!is.character(cluster_ids)||length(cluster_ids)!=length(y)||anyNA(cluster_ids)||any(!nzchar(cluster_ids))) .cr_error('INVALID_CLUSTERS','One nonempty cluster ID per observation');groups<-sort(unique(cluster_ids),method='radix');if(length(groups)<2L||length(y)<=2L) .cr_error('INVALID_CLUSTERS','CR1 requires two clusters and n>2')}else if(!is.null(cluster_ids)) .cr_error('INVALID_COVARIANCE_POLICY','Cluster keys require cluster_cr1')
 if(!(boundary_policy %in% c('reject','clip'))||(boundary_policy=='reject'&&!is.null(epsilon))) .cr_error('INVALID_BOUNDARY_POLICY','Use reject or explicit clipping');used<-p
 if(boundary_policy=='clip') {e<-.cr_numeric(epsilon,'epsilon');if(length(e)!=1L||!is.null(dim(e))||e<=0||e>=.5||1-e==1) .cr_error('INVALID_BOUNDARY_POLICY','Epsilon needs interior representable bounds');used<-pmin(pmax(p,e),1-e)}
 diagnostics<-list(design=d,covariance_policy=covariance_policy,boundary_policy=boundary_policy,epsilon=epsilon,clipped_count=sum(used!=p),confidence_level=confidence,cluster_count=if(is.null(groups))NULL else length(groups),fit_updates_model=FALSE)
 empty<-list(intercept=NULL,slope=NULL,covariance=NULL,standard_errors=NULL,confidence_intervals=NULL,applicability='NOT_APPLICABLE',reason=NULL,converged=FALSE)
 reason<-if(any(used==0|used==1))'BOUNDARY_PD' else if(diff(range(used))==0)'CONSTANT_PD' else if(length(unique(y))<2L)'ONE_CLASS' else NULL
 if(!is.null(reason)) {empty$reason<-reason;return(.cr_result(empty,'validation.calibration_intercept_slope','calibration_diagnostic',context,diagnostics=diagnostics))}
 x<-stats::qlogis(used)
 fit<-tryCatch(fit_binary_glm(matrix(x,ncol=1),y,link='logit',feature_order='frozen_log_odds',fit_intercept=TRUE,target=d$target,training=list(data_fingerprint=.cr_hash(list(pd=as.list(p),outcomes=as.list(y))),split_id=d$split_id,known_at=d$evaluation_at),model_id='calibration-diagnostic',model_version='1.0',max_iter=max_iter,tolerance=tolerance),creditratingsystem_error=function(e)e)
 if(inherits(fit,'creditratingsystem_error')) {if(!(fit$code %in% c('SEPARATION','NON_CONVERGENCE','RANK_DEFICIENT','NON_IDENTIFIABLE','NUMERICAL_FAILURE')))stop(fit);empty$reason<-fit$code;diagnostics$fit_error<-fit$details;return(.cr_result(empty,'validation.calibration_intercept_slope','calibration_diagnostic',context,diagnostics=diagnostics))}
 beta<-unlist(fit$model$parameters$coefficients);covariance<-do.call(rbind,lapply(fit$model$parameters$covariance,unlist));critical<-stats::qnorm((1+confidence)/2)
 if(!is.null(groups)) {X<-cbind(1,x);residual<-y-stats::plogis(as.vector(X%*%beta));scores<-do.call(rbind,lapply(groups,function(g)colSums(X[cluster_ids==g,,drop=FALSE]*residual[cluster_ids==g])));adjustment<-length(groups)/(length(groups)-1)*(length(y)-1)/(length(y)-2);covariance<-covariance%*%crossprod(scores)%*%covariance*adjustment;covariance<-(covariance+t(covariance))/2;critical<-stats::qt((1+confidence)/2,length(groups)-1);diagnostics$cluster_correction<-adjustment;diagnostics$reference_distribution<-'Student-t';diagnostics$reference_df<-length(groups)-1}else diagnostics['reference_distribution']<-list(if(covariance_policy=='iid')'normal' else NULL)
 se<-sqrt(pmax(0,diag(covariance)));matrix_rows<-function(m)lapply(seq_len(nrow(m)),function(i)as.list(unname(m[i,])))
 value<-list(intercept=unname(beta[1]),slope=unname(beta[2]),covariance=if(covariance_policy=='none')NULL else matrix_rows(covariance),standard_errors=if(covariance_policy=='none')NULL else as.list(unname(se)),confidence_intervals=if(covariance_policy=='none')NULL else matrix_rows(cbind(beta-critical*se,beta+critical*se)),applicability='APPLICABLE',reason=NULL,converged=TRUE)
 .cr_result(value,'validation.calibration_intercept_slope','calibration_diagnostic',context,diagnostics=diagnostics,limitations='Diagnostic fit on frozen forecasts; coefficients are not automatically applied. IID and independent-cluster asymptotic intervals do not include original model fitting uncertainty.')
}
calibration_curve<-function(predicted_pd,outcomes,bin_edges,design,interval_method,dependence_assumption,confidence_level=.95,minimum_count=5,context=NULL) {
 s<-.cr_validation_sample(outcomes,predicted_pd,NULL,TRUE);p<-s$p;y<-s$y;d<-.cr_validation_design(design,p);confidence<-.cr_validation_confidence(confidence_level);b<-.cr_validation_bins(p,bin_edges);.cr_data_days(minimum_count,'minimum_count',1)
 if(!(interval_method %in% c('none','clopper_pearson'))) .cr_error('INVALID_INTERVAL_METHOD','Use none or clopper_pearson')
 if(!(dependence_assumption %in% c('descriptive_only','independent_common_probability_within_bins'))||(interval_method=='clopper_pearson'&&dependence_assumption!='independent_common_probability_within_bins')) .cr_error('INCOMPATIBLE_ASSUMPTIONS','Exact intervals need independent common probability within bins')
 rows<-lapply(seq_len(length(b$edges)-1L),function(j){mask<-b$assignment==j;n<-sum(mask);k<-sum(y[mask]);average<-if(n)mean(p[mask]) else NULL;rate<-if(n)k/n else NULL;lower<-upper<-NULL;if(n&&interval_method=='clopper_pearson'){ci<-stats::binom.test(k,n,conf.level=confidence)$conf.int;lower<-unname(ci[1]);upper<-unname(ci[2])};list(bin=j,lower_edge=b$edges[j],upper_edge=b$edges[j+1],upper_closed=j==length(b$edges)-1L,count=n,defaults=k,mean_pd=average,observed_rate=rate,residual=if(n)rate-average else NULL,lower=lower,upper=upper,small_bin=n<minimum_count,status=if(n)'OBSERVED' else 'EMPTY')})
 .cr_result(list(bins=rows,assignments=as.list(b$assignment),total_count=length(y),total_defaults=sum(y)),'validation.calibration_curve','probability',context,diagnostics=list(design=d,interval_method=interval_method,dependence_assumption=dependence_assumption,confidence_level=confidence,minimum_count=minimum_count,boundary_convention='left_closed_last_bin_includes_one'),limitations='Bins must be chosen before inspecting outcomes. Exact count intervals assume common independent event probability within each bin; none is the appropriate descriptive policy when this is unsupported.')
}
spiegelhalter_test<-function(predicted_pd,outcomes,design,alternative,independence_assumption,context=NULL) {
 s<-.cr_validation_sample(outcomes,predicted_pd,NULL,TRUE);p<-s$p;y<-s$y;d<-.cr_validation_design(design,p);.cr_validation_alternative(alternative);if(!identical(independence_assumption,'independent_fixed_bernoulli')) .cr_error('INCOMPATIBLE_ASSUMPTIONS','Require independent_fixed_bernoulli')
 numerator<-sum((y-p)*(1-2*p));terms<-p*(1-p)*(1-2*p)^2;variance<-sum(terms);z<-pvalue<-NULL;status<-'NOT_APPLICABLE';reason<-'ZERO_VARIANCE'
 if(variance>0){z<-numerator/sqrt(variance);pvalue<-if(alternative=='two-sided')2*stats::pnorm(-abs(z)) else if(alternative=='less')stats::pnorm(z) else stats::pnorm(z,lower.tail=FALSE);status<-'APPLICABLE';reason<-NULL}
 .cr_result(list(z=z,numerator=numerator,variance=variance,p_value=pvalue,applicability=status,reason=reason),'validation.spiegelhalter_test','test',context,diagnostics=list(design=d,alternative=alternative,independence_assumption=independence_assumption,maximum_variance_share=if(variance==0)NULL else max(terms)/variance,reference_distribution='asymptotic_standard_normal'),limitations='Normal approximation needs an adequate non-dominant sum of Bernoulli terms. This statistic tests one calibration moment and is not an omnibus test; zero variance has no defined Z.')
}
poisson_binomial_pd_test<-function(individual_pd,observed_default_count,design,alternative,independence_assumption,method='dynamic_programming',context=NULL) {
 p<-.cr_probability(individual_pd,vector_only=TRUE);d<-.cr_validation_design(design,p);.cr_validation_alternative(alternative);k<-.cr_numeric(observed_default_count,'observed_default_count');if(length(k)!=1L||!is.null(dim(k))||k<0||k>length(p)||k!=floor(k)) .cr_error('INVALID_COUNTS','Default count must be integer in [0,n]');if(!identical(independence_assumption,'independent_fixed_bernoulli')) .cr_error('INCOMPATIBLE_ASSUMPTIONS','Require independent_fixed_bernoulli');if(!identical(method,'dynamic_programming')) .cr_error('INVALID_METHOD','Supported method is dynamic_programming')
 pmf<-1;for(prob in p)pmf<-c(pmf*(1-prob),0)+c(0,pmf*prob)
 mass_error<-abs(sum(pmf)-1);minimum<-sum(p==1);maximum<-sum(p>0);underflow<-sum(pmf[seq.int(minimum+1,maximum+1)]==0)
 if(mass_error>1e-10) .cr_error('NUMERICAL_FAILURE','Convolution lost probability mass')
 tail<-if(alternative=='less')sum(pmf[seq_len(k+1)]) else if(alternative=='greater')sum(pmf[seq.int(k+1,length(pmf))]) else sum(pmf[pmf<=pmf[k+1]*(1+1e-7)])
 reason<-if(!length(p))'EMPTY_COHORT' else if((alternative=='two-sided'&&pmf[k+1]==0&&k>=minimum&&k<=maximum)||(tail==0&&k>=minimum&&k<=maximum))'NUMERICAL_UNDERFLOW' else NULL
 .cr_result(list(counts=as.list(seq.int(0,length(p))),probability_mass=as.list(pmf),p_value=if(is.null(reason))min(1,tail) else NULL,expected_count=sum(p),variance=sum(p*(1-p)),applicability=if(is.null(reason))'APPLICABLE' else 'NOT_APPLICABLE',reason=reason),'validation.poisson_binomial_pd_test','test',context,diagnostics=list(design=d,alternative=alternative,independence_assumption=independence_assumption,method=method,mass_error=mass_error,underflowed_support_cells=underflow,two_sided_ordering='probability_mass',mass_order_relative_tolerance=1e-7),limitations='Exact finite-precision dynamic programming takes quadratic work in trial count. Model estimation uncertainty and dependence are not included in this conditional null.')
}
hosmer_lemeshow_test<-function(predicted_pd,outcomes,bin_edges,design,degrees_of_freedom_policy,independence_assumption,minimum_expected=5,context=NULL) {
 s<-.cr_validation_sample(outcomes,predicted_pd,NULL,TRUE);p<-s$p;y<-s$y;d<-.cr_validation_design(design,p,TRUE);b<-.cr_validation_bins(p,bin_edges);threshold<-.cr_numeric(minimum_expected,'minimum_expected');if(length(threshold)!=1L||!is.null(dim(threshold))||threshold<=0) .cr_error('INVALID_INPUT','minimum_expected must be positive');if(!identical(independence_assumption,'independent_fixed_bernoulli')) .cr_error('INCOMPATIBLE_ASSUMPTIONS','Require independent_fixed_bernoulli');if(!(degrees_of_freedom_policy %in% c('external_common_bin_pd','fitted_logistic_approximation'))) .cr_error('INVALID_DF_POLICY','Declare external_common_bin_pd or fitted_logistic_approximation');fitted<-degrees_of_freedom_policy=='fitted_logistic_approximation';if(fitted!=(d$prediction_origin=='FITTED_SAMPLE')) .cr_error('INVALID_VALIDATION_DESIGN','DF policy must match origin')
 rows<-list();reason<-NULL;statistic<-0;active<-0
 for(j in seq_len(length(b$edges)-1L)){mask<-b$assignment==j;n<-sum(mask);observed<-sum(y[mask]);expected<-sum(p[mask]);average<-if(n)expected/n else NULL;contribution<-variance<-NULL;flags<-character()
 if(n){variance<-expected*(1-average);if(variance==0){if(observed!=expected)flags<-c(flags,'IMPOSSIBLE_BIN_OUTCOME')else{contribution<-0;flags<-c(flags,'DETERMINISTIC_BIN')}}else{active<-active+1;contribution<-(observed-expected)^2/variance;statistic<-statistic+contribution;if(min(expected,n-expected)<threshold)flags<-c(flags,'SMALL_EXPECTED_CELL')};if(!fitted&&diff(range(p[mask]))!=0)flags<-c(flags,'HETEROGENEOUS_BIN_PD')}else flags<-c(flags,'EMPTY_BIN')
 invalid<-flags[flags %in% c('IMPOSSIBLE_BIN_OUTCOME','SMALL_EXPECTED_CELL','HETEROGENEOUS_BIN_PD')];if(length(invalid)&&is.null(reason))reason<-invalid[1];rows[[j]]<-list(bin=j,count=n,observed_defaults=observed,expected_defaults=expected,mean_pd=average,variance=variance,contribution=contribution,flags=as.list(flags))}
 df<-if(fitted)active-2 else active;if(df<=0&&is.null(reason))reason<-'NONPOSITIVE_DF';if(any(vapply(rows,function(r)'IMPOSSIBLE_BIN_OUTCOME' %in% unlist(r$flags),logical(1))))statistic<-NULL
 .cr_result(list(statistic=statistic,degrees_of_freedom=df,p_value=if(is.null(reason))stats::pchisq(statistic,df,lower.tail=FALSE) else NULL,bins=rows,applicability=if(is.null(reason))'APPLICABLE' else 'NOT_APPLICABLE',reason=reason),'validation.hosmer_lemeshow_test','test',context,diagnostics=list(design=d,degrees_of_freedom_policy=degrees_of_freedom_policy,independence_assumption=independence_assumption,minimum_expected=as.numeric(threshold),reference_distribution='asymptotic_chi_square'),limitations='The G-2 fitted-logistic policy is an explicitly chosen approximation, not a universal degrees-of-freedom correction. External fixed-bin inference requires common probabilities within each bin. Small expected cells withhold a p-value.')
}
dependent_pd_backtest<-function(predicted_pd,outcomes,cluster_ids,time_ids,design,null_model,innovations,alternative,confidence_level=.95,context=NULL) {
 s<-.cr_validation_sample(outcomes,predicted_pd,NULL,TRUE);p<-s$p;y<-s$y;d<-.cr_validation_design(design,p);.cr_validation_alternative(alternative);confidence<-.cr_validation_confidence(confidence_level);n<-length(y)
 cluster_ids<-unlist(cluster_ids);time_ids<-unlist(time_ids);for(keys in list(cluster_ids,time_ids))if(!is.character(keys)||length(keys)!=n||anyNA(keys)||any(!nzchar(keys))) .cr_error('INVALID_CLUSTERS','One cluster and time key per row required')
 ids<-d$observation_ids;if(!is.list(ids)||length(ids)!=n||anyDuplicated(unlist(ids))||any(!vapply(ids,function(i)is.character(i)&&length(i)==1L&&!is.na(i)&&nzchar(i),logical(1)))) .cr_error('INVALID_VALIDATION_DESIGN','Unique ordered observation_ids required')
 if(!.cr_object(null_model)||!.cr_object(innovations)) .cr_error('INVALID_NULL_MODEL','Explicit model and innovation objects required');.cr_canonical(null_model);.cr_canonical(innovations)
 if(!identical(null_model$family,'gaussian_factor')||!identical(innovations$draw_assumption,'independent_standard_normal_rows')) .cr_error('INVALID_NULL_MODEL','Declare Gaussian-factor null and independent normal rows')
 factors<-unique(data.frame(cluster_id=cluster_ids,time_id=time_ids,stringsAsFactors=FALSE));factors<-factors[order(factors$cluster_id,factors$time_id,method='radix'),,drop=FALSE];factor_keys<-lapply(seq_len(nrow(factors)),function(i)list(cluster_id=factors$cluster_id[i],time_id=factors$time_id[i]))
 if(!identical(.cr_hash(innovations$observation_ids),.cr_hash(ids))||!identical(.cr_hash(innovations$factor_keys),.cr_hash(factor_keys))) .cr_error('INNOVATION_ALIGNMENT','Innovation columns must match IDs and sorted cluster/time factors')
 matrix_input<-function(x,name){if(is.list(x)&&is.null(names(x)))x<-do.call(rbind,lapply(x,unlist));.cr_numeric(x,name)}
 Z<-matrix_input(innovations$factor_normals,'factor_normals');E<-matrix_input(innovations$idiosyncratic_normals,'idiosyncratic_normals')
 if(is.null(dim(Z))||is.null(dim(E))||ncol(Z)!=nrow(factors)||!identical(dim(E),c(nrow(Z),n))||nrow(Z)<2L) .cr_error('INCOMPATIBLE_SHAPE','Innovation matrices need B>=2 and declared columns')
 rho<-.cr_probability(if(is.list(null_model$asset_correlation))unlist(null_model$asset_correlation) else null_model$asset_correlation,vector_only=TRUE);if(length(rho)==1L)rho<-rep(rho,n);if(length(rho)!=n) .cr_error('INCOMPATIBLE_SHAPE','Correlation scalar or one per row required')
 C<-matrix_input(null_model$factor_correlation,'factor_correlation');if(!identical(dim(C),c(nrow(factors),nrow(factors)))||any(abs(C-t(C))>1e-12)||any(abs(diag(C)-1)>1e-12)) .cr_error('INVALID_CORRELATION','Factor correlation must be symmetric with unit diagonal')
 L<-tryCatch(chol(C),error=function(e).cr_error('INVALID_CORRELATION','Factor correlation must be positive definite; share keys for perfect common shocks'))
 paths<-Z%*%L;index<-vapply(seq_len(n),function(i)which(factors$cluster_id==cluster_ids[i]&factors$time_id==time_ids[i]),integer(1));latent<-sweep(paths[,index,drop=FALSE],2,sqrt(rho),'*')+sweep(E,2,sqrt(1-rho),'*')
 uncertainty<-null_model$parameter_uncertainty
 if(identical(uncertainty,'conditional_fixed')) {if('parameter_pd_draws' %in% names(innovations)) .cr_error('INVALID_NULL_MODEL','Fixed policy cannot include parameter draws');thresholds<-matrix(rep(stats::qnorm(p),each=nrow(E)),nrow=nrow(E))}else if(identical(uncertainty,'supplied_predictive_pd_draws')) {draws<-.cr_probability(matrix_input(innovations$parameter_pd_draws,'parameter_pd_draws'));if(!identical(dim(draws),dim(E))) .cr_error('INCOMPATIBLE_SHAPE','PD paths must match simulation/observation shape');if(!is.character(null_model$parameter_draw_source)||length(null_model$parameter_draw_source)!=1L||!nzchar(null_model$parameter_draw_source)) .cr_error('INVALID_NULL_MODEL','Parameter draw source required');thresholds<-stats::qnorm(draws)}else .cr_error('INVALID_NULL_MODEL','Declare conditional_fixed or supplied_predictive_pd_draws')
 counts<-rowSums(latent<=thresholds);expected<-sum(p);observed<-sum(y);statistic<-observed-expected;null_stat<-counts-expected;tail<-if(alternative=='less')null_stat<=statistic else if(alternative=='greater')null_stat>=statistic else abs(null_stat)>=abs(statistic);B<-length(counts);extreme<-sum(tail);pvalue<-(extreme+1)/(B+1);ci<-stats::binom.test(extreme,B,conf.level=confidence)$conf.int;prediction<-as.numeric(stats::quantile(counts,c((1-confidence)/2,(1+confidence)/2),type=1,names=FALSE))
 .cr_result(list(observed_count=observed,expected_count=expected,statistic=statistic,p_value=pvalue,null_counts=as.list(counts),null_statistics=as.list(null_stat),null_count_interval=as.list(prediction),tail_probability_interval=as.list(as.numeric(ci)),applicability='APPLICABLE',reason=NULL),'validation.dependent_pd_backtest','test',context,diagnostics=list(design=d,null_model=null_model,alternative=alternative,confidence_level=confidence,replicates=B,extreme_replicates=extreme,p_value_resolution=1/(B+1),innovation_fingerprint=.cr_hash(innovations),factor_keys=factor_keys,monte_carlo_rule='(extreme+1)/(B+1)',two_sided_ordering='absolute_count_residual',parameter_uncertainty=uncertainty),limitations='Inference is conditional on the declared dependence null and exchangeable independent simulation rows. Supplied parameter draws define a predictive mixture, not an automatically estimated frequentist sampling distribution. Tail-probability intervals measure Monte Carlo error, and count intervals are null prediction intervals.')
}
default_count_backtest<-function(observation_panel,frozen_forecasts,group_by,unit,horizon_days,default_definition,redefault_policy,evaluation_cutoff,context=NULL) {
 rows<-.cr_data_rows(observation_panel,'observation_panel');forecasts<-.cr_data_rows(frozen_forecasts,'frozen_forecasts');.cr_data_unique(rows,'observation_id','observation_panel');.cr_data_unique(forecasts,'observation_id','frozen_forecasts');horizon<-.cr_data_days(horizon_days,'horizon_days',1);cutoff<-.cr_data_date(evaluation_cutoff,'evaluation_cutoff')
 if(!(unit %in% c('obligor','facility'))||!identical(redefault_policy,'exclude_previous_default')) .cr_error('INVALID_COHORT_POLICY','Declare unit and exclude_previous_default');if(!is.character(default_definition)||length(default_definition)!=1L||!nzchar(default_definition)) .cr_error('INVALID_COHORT_POLICY','Nonempty default definition required');group_by<-unlist(group_by);if(length(group_by)&&(!is.character(group_by)||anyNA(group_by)||any(!nzchar(group_by))||anyDuplicated(group_by))) .cr_error('INVALID_COHORT_POLICY','group_by requires distinct names')
 known_ids<-vapply(rows,function(r)r$observation_id,character(1));forecast_ids<-vapply(forecasts,function(f)f$observation_id,character(1));if(any(!forecast_ids %in% known_ids)) .cr_error('FORECAST_FOREIGN_KEY','Forecast references unknown observation');forecast_map<-setNames(forecasts,forecast_ids);key<-if(unit=='obligor')'entity_id' else 'facility_id';units<-list();excluded<-list();duplicate_count<-0
 rows<-rows[order(known_ids,method='radix')]
 for(row in rows) {.cr_data_required(row,c('observation_id',key,'as_of','performance_start','outcome_end','eligible','prior_default','default_definition',group_by));if(!is.logical(row$eligible)||length(row$eligible)!=1L||is.na(row$eligible)||!is.logical(row$prior_default)||length(row$prior_default)!=1L||is.na(row$prior_default)||!('target' %in% names(row))) .cr_error('INVALID_COHORT_POLICY','Explicit booleans and possibly null target required')
 start<-.cr_data_date(row$performance_start,'performance_start');end<-.cr_data_date(row$outcome_end,'outcome_end');asof<-.cr_data_date(row$as_of,'as_of');if(start<asof||as.numeric(end-start)!=horizon||row$default_definition!=default_definition) .cr_error('INCOMPATIBLE_TARGET','Observation timing/default definition differs')
 if(!is.null(row$target)){if(!is.numeric(row$target)||length(row$target)!=1L||!(row$target %in% c(0,1))) .cr_error('INVALID_OUTCOMES','Observed target zero/one or missing');.cr_data_required(row,'outcome_known_at');observed_at<-.cr_data_date(row$outcome_known_at,'outcome_known_at');if(observed_at<start||(row$target==0&&observed_at<end)) .cr_error('INVALID_COHORT_POLICY','Outcome known before occurrence/completion')}
 f<-forecast_map[[row$observation_id]];if(is.null(f)){excluded[[length(excluded)+1L]]<-list(observation_id=row$observation_id,reason='MISSING_FORECAST');next}
 .cr_data_required(f,c('pd','forecast_at','known_at','default_definition','horizon_days','unit','probability_measure','model_id','model_version'));prob<-.cr_probability(f$pd);if(length(prob)!=1L||!is.null(dim(prob))) .cr_error('INCOMPATIBLE_SHAPE','Each forecast scalar');created<-.cr_data_date(f$forecast_at,'forecast_at');available<-.cr_data_date(f$known_at,'known_at');if(created>available||available>asof) .cr_error('FORECAST_LEAKAGE','Forecast must be created and known by observation date');if(f$default_definition!=default_definition||f$horizon_days!=horizon||f$unit!=unit||f$probability_measure!='PHYSICAL') .cr_error('INCOMPATIBLE_TARGET','Forecast target/unit differs')
 grouping<-if(length(group_by))row[group_by] else .cr_empty_object();normalized<-list(unit_id=row[[key]],as_of=row$as_of,performance_start=row$performance_start,outcome_end=row$outcome_end,eligible=row$eligible,prior_default=row$prior_default,target=row$target,outcome_known_at=row$outcome_known_at,pd=as.numeric(prob),group=grouping);dedup<-.cr_hash(list(row[[key]],row$as_of,row$performance_start,row$outcome_end))
 if(!is.null(units[[dedup]])){if(!identical(.cr_hash(units[[dedup]]$normalized),.cr_hash(normalized))) .cr_error('DUPLICATE_UNIT_CONFLICT','Repeated default-unit/window differs');duplicate_count<-duplicate_count+1;next}
 reason<-if(asof>cutoff)'FUTURE_OBSERVATION' else if(!row$eligible)'NOT_ELIGIBLE' else if(row$prior_default)'PRIOR_DEFAULT' else if(end>cutoff)'IMMATURE' else if(is.null(row$target))'MISSING_OUTCOME' else if(observed_at>cutoff)'OUTCOME_NOT_YET_KNOWN' else NULL
 units[[dedup]]<-list(normalized=normalized,reason=reason,observation_id=row$observation_id)
 }
 groups<-list()
 for(record in units){info<-record$normalized;digest<-.cr_hash(info$group);if(is.null(groups[[digest]]))groups[[digest]]<-list(group=info$group,unit_windows=0,observed_count=0,observed_defaults=0,expected_defaults=0,exclusions=list());g<-groups[[digest]];g$unit_windows<-g$unit_windows+1
 if(!is.null(record$reason)){item<-list(observation_id=record$observation_id,reason=record$reason);g$exclusions[[length(g$exclusions)+1L]]<-item;excluded[[length(excluded)+1L]]<-item}else{g$observed_count<-g$observed_count+1;g$observed_defaults<-g$observed_defaults+info$target;g$expected_defaults<-g$expected_defaults+info$pd};groups[[digest]]<-g}
 finish<-function(g){expected<-g$expected_defaults;observed<-g$observed_defaults;g['observed_expected_ratio']<-list(if(expected==0)NULL else observed/expected);g$ratio_status<-if(expected==0&&observed>0)'INFINITE' else if(expected==0)'UNDEFINED' else 'FINITE';g['observed_rate']<-list(if(g$observed_count==0)NULL else observed/g$observed_count);g['mean_pd']<-list(if(g$observed_count==0)NULL else expected/g$observed_count);g}
 output<-unname(lapply(groups[sort(names(groups),method='radix')],finish));total<-function(field)sum(vapply(output,function(g)g[[field]],numeric(1)));overall<-finish(list(unit_windows=total('unit_windows'),observed_count=total('observed_count'),observed_defaults=total('observed_defaults'),expected_defaults=total('expected_defaults')))
 if(length(excluded))excluded<-excluded[order(vapply(excluded,function(e)e$observation_id,character(1)),method='radix')]
 .cr_result(list(groups=output,overall=overall,excluded=excluded,deduplicated_rows=duplicate_count),'validation.default_count_backtest','count',context,diagnostics=list(unit=unit,horizon_days=horizon,default_definition=default_definition,redefault_policy=redefault_policy,evaluation_cutoff=evaluation_cutoff,group_by=as.list(group_by),forecast_fingerprint=.cr_hash(forecasts),observation_fingerprint=.cr_hash(.cr_data_rows(observation_panel,'observation_panel')),comparison_population='mature_complete_eligible_unit_windows'),limitations='Only mature complete windows contribute to both observed and expected counts, including when a default is observed early. Repeated time windows may remain dependent; this descriptive report supplies no binomial p-value. Eligibility and default identity are caller-provided evidence.')
}
